/**
 * Units (Daily Teaching System, Parts 3 and 4): /<locale>/units/<slug>.
 *
 * A unit is a list of lessons; a lesson is one teaching point with everything the site already has for it. The page
 * renders ONE generated file per language and nothing else:
 *
 *   content/units/units.<loc>.json   GENERATED by scripts/units/assemble.js from the unit definitions, the content
 *                                    graph, the curriculum registry and the teacher notes
 *   content/units/ui.<loc>.json      the page's own strings (written natively per language)
 *
 * status 'pilot' = noindex, in no sitemap, linked from nowhere (the format pilots of Part 3).
 */
import { deckAssets } from '@/lib/seo/landing-content';

/** rel as it reads IN THE UNIT: 'reviews' = an objective of an earlier year, 'ahead' = of a later year (scripts/units/assemble.js) */
export interface UnitStandard { rel: 'teaches' | 'reviews' | 'ahead' | 'prepares' | 'extends'; framework: string; code: string | null; title: string | null }
export interface UnitPaper { type: string; title: string; core: string; easy?: string; hard?: string; screen?: 1; landing?: string }
export interface UnitLesson {
  n: number;
  point: string;
  title: string;
  objective: string;
  standards: UnitStandard[];
  paper: UnitPaper[];
  tool?: { key: string; slug: string; name: string };
  screen?: { kind: 'activity'; id: string; slug: string; title: string } | { kind: 'page'; slug: string; title: string };
  exit?: { slug: string; title: string };
  maker?: { id: string; name: string; slug: string; template: string };
  note: { mistake: string; words: string; watch: string };
}
export interface Unit {
  id: string;
  slug: string;
  status: 'pilot' | 'live';
  grade: string;
  subject: string;
  title: string;
  metaTitle: string;
  metaDescription: string;
  weeks: number;
  lessons: UnitLesson[];
}
export type UnitUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T;
  try {
    const mod = await importer();
    cache.set(key, mod.default);
    return mod.default as T;
  } catch {
    cache.set(key, null);
    return null;
  }
}
export async function getUnits(locale: string): Promise<Unit[]> {
  const f = await load<{ units: Unit[] }>(`units.${locale}`, () => import(`@/content/units/units.${locale}.json`));
  return f?.units ?? [];
}
export const getUnitUi = (locale: string) => load<UnitUi>(`ui.${locale}`, () => import(`@/content/units/ui.${locale}.json`));

export async function getUnit(locale: string, slug: string): Promise<Unit | null> {
  return (await getUnits(locale)).find((u) => u.slug === slug) ?? null;
}

/** the languages a unit exists in (by its id), for hreflang between real siblings only */
export async function unitSiblings(id: string, locales: readonly string[]): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const l of locales) {
    const u = (await getUnits(l)).find((x) => x.id === id && x.status === 'live');
    if (u) out[l] = u.slug;
  }
  return out;
}

export const fill = (s: string, v: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? `{${k}}`));

/** where a worksheet page of a unit is opened: its landing when it has one, else the page itself (served by nginx) */
export function pageHref(locale: string, slug: string, landing?: string): string {
  return landing ? `/${locale}/worksheets/${landing}` : `/${locale}/decks/${slug}/`;
}
export const pageThumb = (locale: string, slug: string) => deckAssets(locale, slug).thumbnail;
export const pagePdf = (locale: string, slug: string) => deckAssets(locale, slug).pdf;

/** every printable page of a unit, in lesson order: core, easier, harder of each type, then the exit ticket */
export function unitPdfList(locale: string, unit: Unit): string[] {
  const out: string[] = [];
  for (const l of unit.lessons) {
    for (const p of l.paper) { out.push(p.core); if (p.easy) out.push(p.easy); if (p.hard) out.push(p.hard); }
    if (l.exit) out.push(l.exit.slug);
  }
  return [...new Set(out)].map((slug) => pagePdf(locale, slug).replace(/^https?:\/\/[^/]+/, ''));
}

/** the Teacher-only file of a unit, as the gate knows it (lib/teacher-files.ts) */
export const unitGuideFile = (unit: Unit) => `units/${unit.id}/teacher-guide`;
